        <script type="text/javascript">  
    
    function PopulateDataInGrid(response, status, class_id)
    {
        if(status=='success')
        {
            var response_header = response.getAllResponseHeaders().toLowerCase();
            var curr_date_time_valid = false;
            var time_elapsed = 1000000;
            date_pos = response_header.indexOf("date: ");
            response_header = response_header.substring(date_pos+6);
            date_pos = response_header.indexOf("\n");
            response_header = response_header.substring(0,date_pos); //Do not change this value as this datetime string is used
            date_array = response_header.split(" ");
            server_date_now = date_array[1]+date_array[2]+date_array[3];
            server_time_now = timeToSeconds(date_array[4]);
            
            var obj = jQuery.parseJSON(response.responseText);
            var class_index = GetClassIndex(class_id);
       
            var linedUpRowID = 0;
            var delRows = new Array();
            var LBoardIDs = new Array();
            var LBoardArrayIndex = 0;

            var vb_hasNoTimeData = true;
            var vb_hasJO, vb_newDataHasTimeInfo;
            var live_trip_id = 0;
            var vb_r1_time_eliminated = false, vb_r1_faults_eliminated = false;
            
            var vb_round1_clear = false;
            var vb_JOQualified, vb_hasJOQualifiedRows = false, vb_JOGone = false;
            var leaderboard_JO_Rows = new Array();
            var leaderboard_JO_Row_IDs = new Array();
            var leaderboard_JO_Rows_ActOOG = new Array();
            var leaderboard_JO_Rows_Pos = new Array();
            var leaderboard_JO_Gone = new Array();
            var leaderboard_JO_Row_Index = new Array();
            
            var leaderboard_UpcomingJO_Rows = new Array();
            var leaderboard_UpcomingJO_Row_IDs = new Array();
            var leaderboard_UpcomingJO_Rows_ActOOG = new Array();
            var leaderboard_UpcomingJO_Rows_R1Faults = new Array();
            var leaderboard_UpcomingJO_Rows_R1Time = new Array();
            var leaderboard_UpcomingJO_Rows_Index = new Array();
            var inCountdownTrip = -989898;
            
            //After parsing filter the records in leader board and lined up grids
            for(var index=0;index<Number(obj.recs);index++)
            {
                //Set current trip if trip is gone or it is in countdown
                if(obj.curr == obj.rows[index].id && (obj.rows[index].Gone == "1" || !isEmptyValue(obj.rows[index].r1_cd))){
                    inCountdownTrip = !isEmptyValue(obj.rows[index].r1_cd) ? obj.rows[index].id : inCountdownTrip;
                    last_updated_at = obj.curr_updated_at;
                    if(last_updated_at != ""){
                        last_updated_at = last_updated_at.split(" ");
                        last_updated_date = last_updated_at[0];
                        last_updated_time = timeToSeconds(last_updated_at[1]);
                        time_elapsed = server_time_now-last_updated_time;
                        time_in_miliseconds = ((new Date())-(time_elapsed*1000));
                        dateObj = new Date(time_in_miliseconds);
                        if((last_updated_date == server_date_now) && ((time_elapsed)<(300))){ //Last update is within last 5 minutes
                            curr_date_time_valid = true;
                        }
                        
                        //Check that current trip has time and has no update for 20 secs after time populated >>>
                        if(curr_date_time_valid){
                            vb_newDataHasTimeInfo = (!isEmptyValue(obj.rows[index].R1T) || !isEmptyValue(obj.rows[index].JOT));;
                            vb_hasJO = true;
                            if(vb_newDataHasTimeInfo){ //Existing data has time
                                switch(table_type){
                                    //No Jump-off/Jump-off after delay
                                    case 0: 
                                    case 1:
                                    case 5:
                                        vb_hasJO = true;
                                        break;
                                        
                                    //Wait for Jump-Off Time
                                    case 2:
                                        vb_hasJO = true;
                                        if(isEmptyValue(obj.rows[index].R1F)){ //If clean Round 1
                                            vb_hasJO = !isEmptyValue(obj.rows[index].JOT);
                                        }
                                        break;
                                        
                                    //Wait for JO even if R1F > 0    
                                    case 4:
                                        vb_hasJO = !isEmptyValue(obj.rows[index].JOT);
                                        break;
                                }
                                
                                //No update after time was added for 20 seconds
                                if((last_updated_date == server_date_now) && ((time_elapsed)>(20)) && vb_hasJO){ 
                                    curr_date_time_valid = false; //Do not add in live class trips
                                }
                                else{
                                    vb_timeoutSet = true;//Set timeout to refresh data
                                }
                            }
                        }
                        //Check that current trip has time and has no update for 20 secs after time populated <<<
                    }
                    
                    if(curr_date_time_valid){
                        //Class has live trip condition = true
                    }
                    
                    //Append live now arrays and get their trip status
                    LiveTripRows.push(obj.rows[index]);
                    LiveTripRows_elapsedtime.push(time_elapsed);
                    LiveTripRows_validtime.push(curr_date_time_valid);
                    LiveTripRows_classID.push(class_id);
                    LiveTripRows_UpdateTime.push(response_header);
                }

                //Add row in leaderboard
                live_class_obj.class_trips[class_index].leaderboard.push(obj.rows[index]);
                
                /* Class with Seperate JO round */
                vb_JOQualified = false;
                if(obj.rows[index].Gone == "1" && after_delay_jo){
                    vb_round1_clear = isEmptyValue(obj.rows[index].R1F);
                    if(table_type == 5){ //R2 trips are decided based on callbacks if callbacks are set in jumper table type = 5
                        var tripPosition = parseInt(obj.rows[index].Pos);
                        if(JOGRowsCount > 0 && tripPosition > 0 && tripPosition <= JOGRowsCount){
                            vb_round1_clear = true;
                        }
                        else {
                            vb_round1_clear = false;
                        }
                    }
                    vb_round1_clear = vb_round1_clear && !isEmptyValue(obj.rows[index].R1T);
                    vb_round1_clear = vb_round1_clear && !isEliminatedValue(obj.rows[index].R1T) && !isEliminatedValue(obj.rows[index].R1F); //Not eliminated value

                    //check Round is clean OR JO data entered then Trip is JO Qualified
                    vb_JOQualified = vb_round1_clear || !isEmptyValue(obj.rows[index].JOF) || !isEmptyValue(obj.rows[index].JOT);
                    vb_JOQualified = vb_JOQualified && !isEliminatedValue(obj.rows[index].R1T) && !isEliminatedValue(obj.rows[index].R1F); //Not eliminated value in R1
                    if(vb_JOQualified){
                        vb_hasJOQualifiedRows = true;
                        vb_JOGone = !isEmptyValue(obj.rows[index].JOT) || isEliminatedValue(obj.rows[index].JOF);
                        
                        leaderboard_JO_Rows.push(obj.rows[index]);
                        leaderboard_JO_Row_IDs.push(obj.rows[index].id);
                        leaderboard_JO_Rows_ActOOG.push(obj.rows[index].Actual_OOG);
                        leaderboard_JO_Rows_Pos.push(obj.rows[index].Pos);
                        leaderboard_JO_Gone.push(vb_JOGone);
                        leaderboard_JO_Row_Index.push(index);
                        
                        if(vb_JOGone == false){
                            leaderboard_UpcomingJO_Rows.push(obj.rows[index]);
                            leaderboard_UpcomingJO_Row_IDs.push(obj.rows[index].id);
                            leaderboard_UpcomingJO_Rows_ActOOG.push(obj.rows[index].Actual_OOG);
                            leaderboard_UpcomingJO_Rows_R1Faults.push(obj.rows[index].R1F);
                            leaderboard_UpcomingJO_Rows_R1Time.push(obj.rows[index].R1T);
                            leaderboard_UpcomingJO_Rows_Index.push(index);
                            
                            //Append to group arrays
                            UpcomingJO_Rows.push(obj.rows[index]);
                            UpcomingJO_Row_IDs.push(obj.rows[index].id);
                            UpcomingJO_Rows_ActOOG.push(obj.rows[index].Actual_OOG);
                            UpcomingJO_Rows_R1Faults.push(obj.rows[index].R1F);
                            UpcomingJO_Rows_R1Time.push(obj.rows[index].R1T);
                        }
                        else{
                            vb_hasJOGoneTrips = true;
                        }
                    }
                }
                /* Class with Seperate JO round */
                
                //Set ELiminated status for Position column or eliminated trips
                vb_r1_time_eliminated = isEliminatedValue(obj.rows[index].R1T);
                vb_r1_faults_eliminated = isEliminatedValue(obj.rows[index].R1F);
                if(vb_r1_time_eliminated || vb_r1_faults_eliminated){
                    live_class_obj.class_trips[class_index].leaderboard[index].Pos = (vb_r1_time_eliminated ? obj.rows[index].R1T : obj.rows[index].R1F);
                }
                
                vb_hasNoTimeData = (isEmptyValue(obj.rows[index].R1T) && isEmptyValue(obj.rows[index].JOT)); //Check trip has time data 
                live_trip_id = 0;
                if ((obj.rows[index].Gone == "0") || (obj.rows[index].Scr == "1") || (vb_hasNoTimeData && live_trip_id == obj.rows[index].id))               
                    delRows[linedUpRowID++] = index; //delete rows from leaderboard
                else                    
                    LBoardIDs[LBoardArrayIndex++] = index;
            }
           
            //delete from leader board and add in lined up board
            for(var linedUpRowID=(delRows.length-1); linedUpRowID>=0; linedUpRowID--)
            {
                index = delRows[linedUpRowID];
                live_class_obj.class_trips[class_index].leaderboard.splice(index, 1);
		 
                //Ignore already gone trip from lined-up, this trip will not show untill time is entered
                if(obj.rows[index].Gone == "1" || obj.rows[index].id == inCountdownTrip){
                    continue;
                }
                
                //Populate Lined up arrays
                LinedUpRows.push(obj.rows[index]); 
                LinedUpRows_Scr.push(obj.rows[index].Scr);
                LinedUpRows_OOG.push(obj.rows[index].OOG);
                LinedUpRows_ENo.push(obj.rows[index].ENo);
                LinedUpRows_ClassID.push(class_id);
            }
            
            /* Sort based on JO status if class is of Seperate Jump-off and has JO Qualified Trips */
            if(after_delay_jo && vb_hasJOQualifiedRows){
                //Delete JO Qualified Rows
                for(var index=(leaderboard_JO_Rows.length-1); index>=0; index--){
                    // live_class_obj.class_trips[class_index].leaderboard.splice(leaderboard_JO_Row_Index[index], 1);
                    let matchingLeaderboardIndex = live_class_obj.class_trips[class_index].leaderboard.findIndex(x => x.id == leaderboard_JO_Rows[index].id);
                    if(matchingLeaderboardIndex >= 0){
                        live_class_obj.class_trips[class_index].leaderboard.splice(matchingLeaderboardIndex, 1);
                    }
                }
                
                if(table_type == 0){
                    //Sort on Actual Order for JO Qualified trips BUT Jump-Off not gone           
                    array_multisort(leaderboard_UpcomingJO_Rows_ActOOG, 'SORT_ASC', 'SORT_NUMERIC', 
                                leaderboard_UpcomingJO_Rows, 'SORT_ASC', 
                                leaderboard_UpcomingJO_Rows_Index, 'SORT_ASC', 'SORT_NUMERIC',
                                leaderboard_UpcomingJO_Row_IDs, 'SORT_ASC', 'SORT_NUMERIC');
                }
                else if(table_type == 5){
                    //Sort on Reverse order of R1 faults and time for R2 Qualified trips BUT R2 not gone
                    array_multisort(leaderboard_UpcomingJO_Rows_R1Faults, 'SORT_DESC', 'SORT_NUMERIC',
                                leaderboard_UpcomingJO_Rows_R1Time, 'SORT_DESC', 'SORT_NUMERIC', 
                                leaderboard_UpcomingJO_Rows_ActOOG, 'SORT_ASC', 'SORT_NUMERIC',
                                leaderboard_UpcomingJO_Rows, 'SORT_ASC', 
                                leaderboard_UpcomingJO_Rows_Index, 'SORT_ASC', 'SORT_NUMERIC',
                                leaderboard_UpcomingJO_Row_IDs, 'SORT_ASC', 'SORT_NUMERIC');
                }

                //Set upcoming R2 rows in leaderboard
                for(var index = (leaderboard_UpcomingJO_Rows.length-1); index >= 0; index--){
                    leaderboard_UpcomingJO_Rows[index].Pos = "JO";
                    leaderboard_UpcomingJO_Rows[index].UpcomingJO = true;
                    leaderboard_UpcomingJO_Rows[index].JOQualified = true;
                    live_class_obj.class_trips[class_index].leaderboard.splice(0, 0, leaderboard_UpcomingJO_Rows[index]);
                }

                //Sort JO Round Gone trips based on their positions >>>               
                array_multisort(leaderboard_JO_Rows_Pos, 'SORT_ASC', 'SORT_NUMERIC', 
                            leaderboard_JO_Rows_ActOOG, 'SORT_ASC', 'SORT_NUMERIC', 
                            leaderboard_JO_Rows, 'SORT_ASC', 
                            leaderboard_JO_Row_Index, 'SORT_ASC', 'SORT_NUMERIC',
                            leaderboard_JO_Gone, 'SORT_ASC', 'SORT_NUMERIC',
                            leaderboard_JO_Row_IDs, 'SORT_ASC', 'SORT_NUMERIC');
            
                for(var index = (leaderboard_JO_Rows.length-1); index >= 0; index--){
                    if(leaderboard_JO_Gone[index]){    
                        leaderboard_JO_Rows[index].Pos = "JO";
                        leaderboard_JO_Rows[index].JOGone = true;
                        leaderboard_JO_Rows[index].JOQualified = true;
                        live_class_obj.class_trips[class_index].leaderboard.splice(0, 0, leaderboard_JO_Rows[index]);
                    }
                }
                //Sort JO Round Gone trips based on their positions <<<
                
            }
            /* Sort based on JO status if class is of Seperate Jump-off and has JO Qualified Trips */

            setPositions(class_id); //Set Valid positions
            
        }
    }
    
    function setPositions(class_id){
        //Set Valid positions
        var class_index = GetClassIndex(class_id);
        var copy_obj = live_class_obj.class_trips[class_index].leaderboard;
        var listData = JSON.parse(JSON.stringify(copy_obj)); //copy_obj.slice();
        var vl_position = 0;
        var last_position = -88; //invalid value
        for(var NewRowCount=0; NewRowCount<listData.length;NewRowCount++){

            //Trip is not eliminated trip
            if(!isEliminatedValue(listData[NewRowCount].Pos)){
                if(listData[NewRowCount].Pos != last_position){ //Check same position for last row
                    vl_position++;
                }

                if(after_delay_jo && listData[NewRowCount].Pos.toString().indexOf("JO")>=0 && isEmptyValue(listData[NewRowCount].JOT) && !isEliminatedValue(listData[NewRowCount].JOF)){
                    live_class_obj.class_trips[class_index].leaderboard[NewRowCount].Pos = "JO-" + vl_position; //Set position for trips not gone in JO Round
                }
                else{
                    live_class_obj.class_trips[class_index].leaderboard[NewRowCount].Pos = vl_position.toString();
                }
                
                //Update Position for JO Rows to ensure Position counter change
                if(listData[NewRowCount].Pos.toString().indexOf("JO")>=0){
                    listData[NewRowCount].Pos = listData[NewRowCount].Pos + "-" + NewRowCount; 
                }
                last_position = listData[NewRowCount].Pos;
            }
        }
    }
    
    function PopulateLinedUp(class_id){
        var trips_to_go = 0; 
        var class_index = GetClassIndex(class_id);
        live_class_obj.class_trips[class_index].lined_up = [];
        live_class_obj.next_trip = {};
        vb_upNextRowAdded = false;
        
        var lined_in_pos = 0;
        var lined_up_rows = 1;
        var lined_up_entries = new Array();
        var class_lined_up_entries = new Array();
        
        //Sort Lined up rows on OOG and Entry No.
        array_multisort(LinedUpRows_Scr, 'SORT_ASC', 'SORT_NUMERIC',
                            LinedUpRows_OOG, 'SORT_ASC', 'SORT_NUMERIC', 
                            LinedUpRows_ENo, 'SORT_ASC', 'SORT_NUMERIC',
                            LinedUpRows, 'SORT_ASC',
                            LinedUpRows_ClassID, 'SORT_ASC');
                
        
        for(var counter=0; counter < LinedUpRows.length; counter++){
            if(lined_up_entries.indexOf(LinedUpRows[counter].ENo) < 0){ //Show One trip of Multiple trips of same entry once
                lined_up_entries.push(LinedUpRows[counter].ENo);
                lined_in_pos = order_of_go_set ? lined_up_rows : "";
                lined_up_rows++;

                if (LinedUpRows[counter].Scr == "0"){
                    trips_to_go++;
                    
                    if(!vb_upNextRowAdded && order_of_go_set){ //Set UP NEXT ROW
                        live_class_obj.next_trip = LinedUpRows[counter];
                        vb_upNextRowAdded = true;
                    }
                }
            }
            
            if(LinedUpRows_ClassID[counter] == class_id && class_lined_up_entries.indexOf(LinedUpRows[counter].ENo) < 0){ //Push lined up trips of current class
                live_class_obj.class_trips[class_index].lined_up.push(LinedUpRows[counter]);
                class_lined_up_entries.push(LinedUpRows[counter].ENo);
            }
        }
        
        //If JUMP-OFF is after some delay and Some Trips JO is gone
        if(after_delay_jo && vb_hasJOGoneTrips){
            live_class_obj.next_trip = {};
            vb_upNextRowAdded = false;
        }
        
        //Set Up Next Horse for rounds whose JUMP-OFF is after some delay of 1st round
        if(table_type == 0){///Sort on Actual Order for JO Qualified trips BUT Jump-Off not gone
            array_multisort(UpcomingJO_Rows_ActOOG, 'SORT_ASC', 'SORT_NUMERIC', 
                                UpcomingJO_Rows, 'SORT_ASC', 
                                UpcomingJO_Row_IDs, 'SORT_ASC', 'SORT_NUMERIC');
        }
        else if(table_type == 5){
            array_multisort(UpcomingJO_Rows_R1Faults, 'SORT_DESC', 'SORT_NUMERIC',
                                UpcomingJO_Rows_R1Time, 'SORT_DESC', 'SORT_NUMERIC',
                                UpcomingJO_Rows_ActOOG, 'SORT_ASC', 'SORT_NUMERIC', 
                                UpcomingJO_Rows, 'SORT_ASC', 
                                UpcomingJO_Row_IDs, 'SORT_ASC', 'SORT_NUMERIC');
        }
        
        for(vl_upcomingJo_counter=0; vl_upcomingJo_counter<UpcomingJO_Rows.length; vl_upcomingJo_counter++){
            if(LiveTripID != UpcomingJO_Rows[vl_upcomingJo_counter].id){ //ignore live trip from up next if its not yet have JO Data
                if(after_delay_jo && UpcomingJO_Rows.length>0 && (trips_to_go==0 || vb_hasJOGoneTrips)){
                    live_class_obj.next_trip = UpcomingJO_Rows[vl_upcomingJo_counter];
                    vb_upNextRowAdded = true;
                    break;
                }
            }
        }
        
        
        if(!vb_upNextRowAdded){
            live_class_obj.next_trip = {};
            vb_upNextRowAdded = true;
        }
    }
    function PopulateLiveNow(){
        live_class_obj.live_trip = {};
        
        if(LiveTripRows.length > 0){
            //Sort Live Now on basis of time
            array_multisort(
                    LiveTripRows_elapsedtime, 'SORT_ASC', 'SORT_NUMERIC',
                    LiveTripRows_validtime, 'SORT_DESC',
                    LiveTripRows_classID, 'SORT_ASC',
                    LiveTripRows, 'SORT_ASC',
                    LiveTripRows_UpdateTime, 'SORT_ASC');
                  
            if(LiveTripRows_validtime[0] == true){ //Most recent trip is live
                live_class_obj.live_trip = LiveTripRows[0];
                LiveTripID = LiveTripRows[0].id;
                
                //Pyramid timing fields (pt, r1_cd, r1_start, r1_start_time, r1_done, jo_cd, jo_start, jo_start_time, jo_done, time_4d)
                curr_status = "";
                if(LiveTripRows[0].pt == true || LiveTripRows[0].pt == "1"){ //Handle Pyramid timing data
                    fromPyramid = true;
                    //Get current GMT time from JSON reponse header instead of client time
                    var current_time = getGMTDateTime(new Date(LiveTripRows_UpdateTime[0]));
                    var json_time = ""; 
                    var countdown_limit = 0;
                    //var now = new Date(); 
                    //current_time = getGMTDateTime(now);
                    
                    //Check JO Round info first
                    if(isEmptyValue(LiveTripRows[0].JOT)){
                        which_round = "JO";
                        
                        if(!isEmptyValue(LiveTripRows[0].jo_done)){
                            curr_status = "TS"; //Stop JO timer
                        }
                        else if(!isEmptyValue(LiveTripRows[0].jo_start)){ //Show Round 1 Timer
                            curr_status = "TA"; //JO timer active 
                            json_time = getGMTDateTime(new Date(LiveTripRows[0].jo_start)); 
                        }
                        else if(!isEmptyValue(LiveTripRows[0].jo_cd) && isEmptyValue(LiveTripRows[0].JOF)){ 
                            curr_status = "CDA"; //JO countdown timer active
                            json_time = getGMTDateTime(new Date(LiveTripRows[0].jo_cd));
                            countdown_limit = jo_countdown_limit;
                        }
                    }
                    
                    //Check Round 1 only if trip has No JO round info
                    if(isEmptyValue(LiveTripRows[0].R1T) && isEmptyValue(curr_status) && isEmptyValue(LiveTripRows[0].JOT)){
                        which_round = "R1";
                        if(!isEmptyValue(LiveTripRows[0].r1_done)){
                            curr_status = "TS"; //Stop Round 1 timer
                        }
                        else if(!isEmptyValue(LiveTripRows[0].r1_start)){ //Show Round 1 Timer
                            curr_status = "TA"; //Round 1 timer active  
                            json_time = getGMTDateTime(new Date(LiveTripRows[0].r1_start));
                           
                        }
                        else if(!isEmptyValue(LiveTripRows[0].r1_cd) && isEmptyValue(LiveTripRows[0].R1F)){ 
                            curr_status = "CDA"; //Round 1 countdown timer active
                            json_time = getGMTDateTime(new Date(LiveTripRows[0].r1_cd)); //Date function converts date to localized datetime, we must re extract GMT date time
                            countdown_limit = r1_countdown_limit;
                        }
                    }
                    
                    //Set Current running time
                    switch(curr_status){
                        case "TS":
                            break;

                        case "TA":
                            curr_running_time = current_time.getTime() - json_time.getTime(); //Get difference between two times
                            curr_running_time = Math.round(curr_running_time/1000); //Get no. of seconds
                            curr_running_time -= pyramid_timer_offset;
                            curr_running_time = curr_running_time <= 0 ? 0 : curr_running_time;
                            break;

                        case "CDA":
                            curr_running_time = current_time.getTime() - json_time.getTime(); //Get difference between two times
                            curr_running_time = curr_running_time <= 0 ? 0 : curr_running_time;
                            curr_running_time = countdown_limit - Math.round(curr_running_time/1000); //Get no. of seconds
                            curr_running_time += pyramid_timer_offset;
                            break;
                    }

                    if(!isEmptyValue(curr_status)){ //Round 1 and Jump-off time is empty'
                        show=true;
                        startTIME();
                    }
                }
                else{
                   clearALL();
                }
                
                
                //Delete Live Trip with No Score from Leaderboard
                var class_index = GetClassIndex(LiveTripRows_classID[0]);
                var copy_obj = live_class_obj.class_trips[class_index].leaderboard;
                var listData = JSON.parse(JSON.stringify(copy_obj)); //copy_obj.slice();
                for(var NewRowCount=0; NewRowCount<listData.length;NewRowCount++){
                    if(listData[NewRowCount].id == LiveTripID){
                        if((isEmptyValue(listData[NewRowCount].R1T) && isEmptyValue(listData[NewRowCount].JOT))){ //Trip has no time data
                            live_class_obj.class_trips[class_index].leaderboard.splice(NewRowCount, 1);
                            setPositions(LiveTripRows_classID[0]);
                            break;
                        }
                    }
                }

            }
            else{
                //Most recent trip not live
            }
        }
    }
    
