    function getJumperTableType(table_name){
        var type = 1;
        switch(table_name){

            //Jump-Off after delay, Remove after 20 seconds for Round 1 Time
            case "USEF Table II.2.a":
            case "FEI Rule 220.2.1.2":
            case "FEI Rule 238.2.2":
                type = 0; 
                break;

            //No Jump-Off Round, remove after 20 seconds of R1T and no update
            case "USEF Table II":
            case "USEF Table II.1":
            case "USEF Table II.2.1":
            case "USEF Table III":
            case "USEF Table IV":
            case "FEI Rule 220.2.1.1":
            case "FEI Rule 225":
            case "FEI Rule 238.2.1":
            case "FEI Rule 239":
                type = 1; 
                break;

            //Wait for Jump off time
            case "USEF Table II.2.b":
            case "USEF Table II.2.ab":
            case "USEF Table II.2.c":
            case "USEF Table IV.2.b":
            case "FEI Rule 222.1.4.2":
            case "FEI Rule 222.1.4.3":
            case "FEI Rule 274.1.5.2":
            case "FEI Rule 274.1.5.3":
            case "FEI Rule 274.5.3":
                type = 2; 
                break;
                
            //Always have JO even if R1 not clean
            case 'FEI Rule 222.2.3':
            case "FEI Rule 274.5.6":
            case "FEI Rule 274.2.5":
            case "USEF Table II.2.d":
                type = 4; 
                break;
            
            // Jump-Off after delay but but Round 2 goes in reverse order of score (faults + time)
            case 'FEI Rule 221.4.3(i)':
            case 'FEI Rule 223.1':
            case 'FEI Rule 223.2':
            case "FEI Rule 276.1":
            case "FEI Rule 276.2":
                type = 5;
                break;

        } 
        return type;
    }

    function classGroupHasAggregateFaults(classGroup){
