        }
        else if(['FEI Rule 221.4.3(i)'].includes(classGroup.jumper_table)){ //list of jumper tables which need aggregate faults
            return true;
        }

        return false;
    }
    
    //Get Table type
    var jumper_table = "USEF Table II.2.b";
    var table_type = getJumperTableType(jumper_table);
    var after_delay_jo = table_type == 0 || table_type == 5;
    
