<script language="javascript"> 
    var base = 60;
    var pyramid_timer_enabled = true;
    var pyramid_timer_offset = 0;
    var start = new Date().getTime(),last_time = 0, last_curr_status = "", last_which_round = "", last_current_trip = -1;
    var r1_countdown_limit = 45, jo_countdown_limit = 45;
    var clocktimer,dateObj,dh,dm,ds,ms;
    var readout='';
    var h=1;
    var m=1;
    var tm=1;
    var s=0;
    var ts=0;
    var ms=0;
    var show=true;
    var init=0;
    var curr_running_time=0;
    var curr_status=null;
    var which_round=null;
    var fromPyramid=false;
    var mPLUS=new Array(
        'm0',
        'm1',
        'm2',
        'm3',
        'm4',
        'm5',
        'm6',
        'm7',
        'm8',
        'm9'
    );
    
    function clearALL() {
        fromPyramid = false;
        which_round = "";
        curr_status = "";
	clearTimeout(clocktimer);
	h=1;m=1;tm=1;s=0;ts=0;ms=0;
	init=0;show=true;
	readout='';
        curr_running_time=0;
        start = new Date().getTime();
        last_time = 0;
        elapsed = '0.0';
    }
    
    function startTIME() {
        live_class_obj.live_trip.timer = {};
        clearTimeout(clocktimer); //clear timeout
        if(pyramid_timer_enabled == false){ //Pref to disable pyramid offset timers
            return false;
        }
            
        if(fromPyramid==true){
            if	(curr_status ==	'CDX'){  // countdown stopped
                readout = 'CD: ' + curr_running_time;
            }
            else if(curr_status == 'CDA') {  // countdown active
                curr_running_time=((curr_running_time*1000)-100)/1000;
                if(curr_running_time <= 0){
                    //show = false;
                    readout = "";
                }
                else{
                    readout = 'CD: ' + (Math.floor(curr_running_time * 1001) / 1000).toFixed(0);
                }
            }
            else if(curr_status == 'TS'){  // time stopped
                readout = curr_running_time > 0 ? (Math.floor(curr_running_time * 1001) /1000).toFixed(2) : "";
            }
            else if (curr_status == 'TA') {  // time active
                curr_running_time=((curr_running_time*1000)+100)/1000;
                //readout= (Math.floor(curr_running_time * 1001) /1000).toFixed(1) + "" + Math.floor((Math.random()*10)+0); //Randomize second decimal
                readout= (Math.floor(curr_running_time * 1001) /1000).toFixed(0); //Show seconds only not microseconds
            }
        }
        else{
            var cdateObj = new Date();
            var t = (cdateObj.getTime() - dateObj.getTime())-(s*1000);

            while(t>999){
                t-=1000;
                s++;
            }
            ts=parseInt((ms/100)+s);
            if(ts>=base) { ts=ts-((m-1)*base); }
        
            ms = Math.round(t/10);
            if (ms>99) {ms=0;}
            if (ms==0) {ms='00';}
            if (ms>0&&ms<=9) { ms = '0'+ms; }

            if (ts>0) { ds = ts; if (ts<10) { ds = '0'+ts; }} else { ds = '00'; }
            readout = ds + '.' + ms;
            var timehtml = "";
        }
        
        if(isEmptyValue(curr_status) || isNaN(curr_running_time)){
            curr_running_time = 0;
            curr_status = "";
            readout = "";
        }
        
        //Check if Round has time data
        if(isEmptyValue(curr_status)){
            clearTimeout(clocktimer); //clear timeout
        }
        else{
            if(show){
                if(curr_status == 'CDX' || curr_status == 'CDA'){
                    live_class_obj.live_trip.timer = {
                        countdown: true,
                        value: readout,
                        round: which_round
                    };
                } else {
                    live_class_obj.live_trip.timer = {
                        countdown: false,
                        value: readout,
                        round: which_round
                    };  
                }
                live_class_obj.has_update = true;
            }

            if(readout>=200){
                show = false;
                live_class_obj.live_trip.timer.value = {};
            }
            else{
                //Trip/Round/Status changed then reset time offset to build accurate timer
                var diff = 0;
                var interval = 100;
                if(LiveTripID != last_current_trip || last_curr_status != curr_status || last_which_round != which_round){
                    start = new Date().getTime();
                    last_time = 0;
                }
                else{
                    last_time += interval;
                    diff = (new Date().getTime() - start) - last_time;
                }
                clocktimer = setTimeout("startTIME()", (interval-diff));

                //Update variables
                last_current_trip = LiveTripID;
                last_curr_status = curr_status;
                last_which_round = which_round;

            }
        }
    }
    
    function findTIME() {
        if (init==0) {
            dateObj = new Date();
            startTIME();
            init=1;
	} else {
            if(show==true) {
		show=false;
            } else {
		show=true;
            }
	}
    }

</script>

