    function HighlightUpdates(oldData, class_id){
        var new_pos, old_pos;
        var class_index = GetClassIndex(class_id);
        var copy_obj = live_class_obj.class_trips[class_index].leaderboard;
        var newData = JSON.parse(JSON.stringify(copy_obj)); //copy_obj.slice();
        for(var NewRowCount=0; NewRowCount<newData.length;NewRowCount++){

            //Ignore Delta for eliminated trips
            if(isEliminatedValue(newData[NewRowCount].Pos)){
                continue;
            }

            var foundinold = false;
            var hasupdate = false;
            var delta = "";
            newid = newData[NewRowCount].id;
            for(var OldRowCount=0; OldRowCount<oldData.length;OldRowCount++){
                oldid = oldData[OldRowCount].id;
                if(newid == oldid){
                    foundinold = true;
                    if(newData[NewRowCount].Pos != oldData[OldRowCount].Pos){
                        delta = oldData[OldRowCount].Pos - newData[NewRowCount].Pos;
                        if(isNaN(delta)){ //Calculate delta when NaN
                            new_pos = parseInt(newData[NewRowCount].Pos.match(/\d/g).join(""));
                            old_pos = parseInt(oldData[OldRowCount].Pos.match(/\d/g).join(""));
                            delta = old_pos - new_pos;
                        }
                    }


                    if(class_type == "Jumpers"){ //Check jumper class fields (R1T, R1F, J0T, JOF)
                        if((newData[NewRowCount].R1F != oldData[OldRowCount].R1F)||(newData[NewRowCount].R1T != oldData[OldRowCount].R1T)||(newData[NewRowCount].JOF != oldData[OldRowCount].JOF)||(newData[NewRowCount].JOT != oldData[OldRowCount].JOT)){
                            hasupdate = true;
                        }
                    }
                    else{ //Check J1, J2, J3, .. J6
                        if((newData[NewRowCount].J1 != oldData[OldRowCount].J1)||(newData[NewRowCount].J2 != oldData[OldRowCount].J2)||(newData[NewRowCount].J3 != oldData[OldRowCount].J3)
                                || (newData[NewRowCount].J4 != oldData[OldRowCount].J4)||(newData[NewRowCount].J5 != oldData[OldRowCount].J5)||(newData[NewRowCount].J6 != oldData[OldRowCount].J6)){
                            hasupdate = true;
                        }
                    }
                    break;
                }
            }

            if(!foundinold){
                delta = newData.length-newData[NewRowCount].Pos+1;
                continue; //Do not show delta for row just slotted-in
            }
            else if(isNaN(delta)){
                delta = newData.length-newData[NewRowCount].Pos;
            }

            //Safety check to bypass invalid value
            if(isNaN(delta)){
                delta = newData.length - NewRowCount;
            }

            //Set delta
            live_class_obj.class_trips[class_index].leaderboard[NewRowCount].delta = (delta != "") ? delta.toString() : "0";
        }
    }
