<script type="text/javascript">
    function timeToSeconds(time) {
        time = time.split(/:/);
        return time[0] * 3600 + time[1] * 60 + parseInt(time[2]);
    }

    function getNonEmptyValue(value){
        if(value=="" || value=="0" || value=="0.0" || value=="0.00"){
            return "";
        }
        return value;
    }
    function isEmptyValue(value){
        if(value=="" || value=="0" || value=="0.0" || value=="0.00"){
            return true;
        }
